UPDATE public.reading_lessons SET
  title_de = 'Meine Hobbys',
  title_en = 'My Hobbies',
  content_de = 'Jeder Mensch braucht Hobbys. Ich habe viele Hobbys. Mein Lieblingshobby ist Fußball. Ich spiele seit zehn Jahren Fußball. Mein Verein trainiert am Dienstag und am Donnerstag. Am Samstag haben wir oft ein Spiel.

Ich lese gern. Ich lese jeden Abend ein Buch. Jetzt lese ich einen Krimi. Das Buch ist sehr spannend.

Musik ist auch wichtig für mich. Ich höre jeden Tag Musik. Ich spiele Gitarre. Ich lerne seit zwei Jahren Gitarre.

Am Wochenende treffe ich meine Freunde. Wir sehen zusammen einen Film. Letzte Woche haben wir zusammen gekocht. Das war sehr lustig.

Im Sommer fahre ich gern Fahrrad. Was sind eure Hobbys?',
  content_en = 'Every person needs hobbies. I have many hobbies. My favorite hobby is football. I have been playing football for ten years. My club trains on Tuesday and on Thursday. On Saturday we often have a match.

I like reading. I read a book every evening. Now I am reading a crime novel. The book is very exciting.

Music is also important to me. I listen to music every day. I play guitar. I have been learning guitar for two years.

On the weekend I meet my friends. We watch a film together. Last week we cooked together. That was a lot of fun.

In summer I like cycling. What are your hobbies?',
  key_vocabulary = '[{"de":"das Hobby, -s","en":"hobby"},{"de":"der Verein, -e","en":"club"},{"de":"trainieren","en":"to train"},{"de":"das Spiel, -e","en":"game, match"},{"de":"lesen","en":"to read"},{"de":"das Buch, Bücher","en":"book"},{"de":"spannend","en":"exciting"},{"de":"die Musik","en":"music"},{"de":"Gitarre spielen","en":"to play guitar"},{"de":"treffen","en":"to meet"}]'::jsonb,
  questions = '[{"question_de":"Wie lange spielt die Person schon Fußball?","question_en":"How long has the person been playing football?","answer_de":"Sie spielt seit zehn Jahren Fußball.","answer_en":"She has been playing football for ten years."},{"question_de":"Wann trainiert der Verein?","question_en":"When does the club train?","answer_de":"Der Verein trainiert am Dienstag und am Donnerstag.","answer_en":"The club trains on Tuesday and Thursday."},{"question_de":"Wie lange lernt die Person schon Gitarre?","question_en":"How long has the person been learning guitar?","answer_de":"Sie lernt seit zwei Jahren Gitarre.","answer_en":"She has been learning guitar for two years."},{"question_de":"Was haben die Freunde letzte Woche gemacht?","question_en":"What did the friends do last week?","answer_de":"Sie haben zusammen gekocht.","answer_en":"They cooked together."},{"question_de":"Was macht die Person im Sommer gern?","question_en":"What does the person like doing in summer?","answer_de":"Sie fährt gern Fahrrad.","answer_en":"She likes cycling."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Der Verein trainiert am Montag und am Mittwoch.","statement_en":"The club trains on Monday and Wednesday.","answer":"falsch","explanation_de":"Der Verein trainiert am Dienstag und am Donnerstag."},{"type":"rf","statement_de":"Die Person liest jeden Abend eine Zeitung.","statement_en":"The person reads a newspaper every evening.","answer":"falsch","explanation_de":"Die Person liest jeden Abend ein Buch, keine Zeitung."},{"type":"rf","statement_de":"Die Person spielt seit zehn Jahren Fußball.","statement_en":"The person has been playing football for ten years.","answer":"richtig","explanation_de":"Der Text sagt: Ich spiele seit zehn Jahren Fußball."},{"type":"rf","statement_de":"Die Person lernt seit zwei Jahren Gitarre.","statement_en":"The person has been learning guitar for two years.","answer":"richtig","explanation_de":"Der Text sagt: Ich lerne seit zwei Jahren Gitarre."},{"type":"rf","statement_de":"Am Wochenende sieht die Person einen Film.","statement_en":"On the weekend the person watches a film.","answer":"richtig","explanation_de":"Der Text sagt: Wir sehen zusammen einen Film."},{"type":"choice","statement_de":"Was liest die Person gerade?","statement_en":"What is the person reading right now?","options":["einen Krimi","einen Comic"],"answer":"einen Krimi","explanation_de":"Der Text sagt: Jetzt lese ich einen Krimi."}]'::jsonb,
