UPDATE public.reading_lessons SET
  title_de = 'Essen und Trinken',
  title_en = 'Food and Drink',
  content_de = 'Essen und Trinken sind sehr wichtig. Ich esse gern und koche auch gern.

Zum Frühstück esse ich Brot mit Butter und Käse. Ich trinke eine Tasse Kaffee. Ohne Kaffee geht es nicht!

Mittags esse ich oft bei der Arbeit. Ich esse gern Schnitzel mit Pommes. Das Gericht ist typisch deutsch.

Am Abend esse ich Brot mit Wurst. Das heißt Abendbrot.

Ich trinke jeden Tag zwei Liter Wasser. Wasser ist gesund!

Ich koche auch gern selbst. Mein Lieblingsgericht ist Spaghetti Bolognese. Ich kaufe die Zutaten im Supermarkt: Tomaten, Zwiebeln und Hackfleisch. Das Kochen dauert eine Stunde. Das Essen schmeckt fantastisch!

Ich esse auch gern Schokolade, aber nicht zu viel.',
  content_en = 'Food and drink are very important. I like eating and I also like cooking.

For breakfast I eat bread with butter and cheese. I drink a cup of coffee. Without coffee nothing works!

At noon I often eat at work. I like eating schnitzel with fries. The dish is typically German.

In the evening I eat bread with sausage. This is called Abendbrot.

I drink two liters of water every day. Water is healthy!

I also like cooking myself. My favorite dish is spaghetti Bolognese. I buy the ingredients at the supermarket: tomatoes, onions and minced meat. The cooking takes an hour. The food tastes fantastic!

I also like eating chocolate, but not too much.',
  key_vocabulary = '[{"de":"das Frühstück","en":"breakfast"},{"de":"das Abendbrot","en":"cold evening meal"},{"de":"die Tasse, -n","en":"cup"},{"de":"das Brot, -e","en":"bread"},{"de":"der Käse","en":"cheese"},{"de":"das Gericht, -e","en":"dish"},{"de":"kochen","en":"to cook"},{"de":"schmecken","en":"to taste"},{"de":"gesund","en":"healthy"},{"de":"die Zutat, -en","en":"ingredient"}]'::jsonb,
  questions = '[{"question_de":"Was isst die Person zum Frühstück?","question_en":"What does the person eat for breakfast?","answer_de":"Sie isst Brot mit Butter und Käse.","answer_en":"She eats bread with butter and cheese."},{"question_de":"Wo isst die Person mittags?","question_en":"Where does the person eat lunch?","answer_de":"Sie isst mittags oft bei der Arbeit.","answer_en":"She often eats at work at noon."},{"question_de":"Was ist Abendbrot?","question_en":"What is Abendbrot?","answer_de":"Abendbrot ist Brot mit Wurst am Abend.","answer_en":"Abendbrot is bread with sausage in the evening."},{"question_de":"Wie viel Wasser trinkt die Person jeden Tag?","question_en":"How much water does the person drink every day?","answer_de":"Sie trinkt jeden Tag zwei Liter Wasser.","answer_en":"She drinks two liters of water every day."},{"question_de":"Was ist das Lieblingsgericht der Person?","question_en":"What is the person''s favorite dish?","answer_de":"Das Lieblingsgericht ist Spaghetti Bolognese.","answer_en":"The favorite dish is spaghetti Bolognese."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Die Person trinkt zum Frühstück Tee.","statement_en":"For breakfast the person drinks tea.","answer":"falsch","explanation_de":"Die Person trinkt zum Frühstück Kaffee, keinen Tee."},{"type":"rf","statement_de":"Zum Frühstück isst die Person Brot mit Butter und Käse.","statement_en":"For breakfast the person eats bread with butter and cheese.","answer":"richtig","explanation_de":"Der Text sagt: Zum Frühstück esse ich Brot mit Butter und Käse."},{"type":"rf","statement_de":"Die Person trinkt jeden Tag drei Liter Wasser.","statement_en":"The person drinks three liters of water every day.","answer":"falsch","explanation_de":"Die Person trinkt jeden Tag zwei Liter Wasser, nicht drei."},{"type":"rf","statement_de":"Das Lieblingsgericht ist Spaghetti Bolognese.","statement_en":"The favorite dish is spaghetti Bolognese.","answer":"richtig","explanation_de":"Der Text sagt: Mein Lieblingsgericht ist Spaghetti Bolognese."},{"type":"rf","statement_de":"Mittags isst die Person oft bei der Arbeit.","statement_en":"At noon the person often eats at work.","answer":"richtig","explanation_de":"Der Text sagt: Mittags esse ich oft bei der Arbeit."},{"type":"choice","statement_de":"Wo kauft die Person die Zutaten für Spaghetti Bolognese?","statement_en":"Where does the person buy the ingredients for spaghetti Bolognese?","options":["beim Bäcker","im Supermarkt"],"answer":"im Supermarkt","explanation_de":"Der Text sagt: Ich kaufe die Zutaten im Supermarkt."}]'::jsonb,
  word_count = 108,
  estimated_reading_time = 2
