UPDATE public.reading_lessons SET
  title_de = 'Einkaufen in Deutschland',
  title_en = 'Shopping in Germany',
  content_de = 'Ich kaufe jede Woche ein, besonders am Wochenende.

Für Lebensmittel gehe ich zum Supermarkt. Der Supermarkt ist von Montag bis Samstag offen. Am Sonntag ist er nicht offen. Ich kaufe dort einmal pro Woche ein.

Am Samstag gehe ich oft zum Wochenmarkt. Dort kaufe ich Obst und Gemüse von den Bauern. Ich kaufe auch Blumen für meine Wohnung.

Kleidung kaufe ich in der Stadt. Dort gibt es viele Geschäfte. Manchmal kaufe ich Kleidung nicht neu. Das ist gut für die Umwelt.

Ich kaufe auch viel online. Ich bestelle zu Hause. Dann kommt das Paket.

In Deutschland bezahlt man oft bar. Ich bezahle lieber mit meiner EC-Karte.

Ich kaufe nicht zu viel ein. Ich bringe immer meine Einkaufstasche mit.',
  content_en = 'I shop every week, especially on the weekend.

For groceries I go to the supermarket. The supermarket is open Monday to Saturday. On Sunday it is not open. I shop there once a week.

On Saturday I often go to the weekly market. There I buy fruit and vegetables from the farmers. I also buy flowers for my apartment.

I buy clothes in the city. There are many shops there. Sometimes I buy clothes that are not new. That is good for the environment.

I also buy a lot online. I order at home. Then the package arrives.

In Germany people often pay cash. I prefer paying with my debit card.

I don''t buy too much. I always bring my shopping bag.',
  key_vocabulary = '[{"de":"einkaufen","en":"to shop"},{"de":"das Geschäft, -e","en":"shop"},{"de":"der Supermarkt, -märkte","en":"supermarket"},{"de":"der Markt, Märkte","en":"market"},{"de":"bestellen","en":"to order"},{"de":"das Paket, -e","en":"package"},{"de":"bezahlen","en":"to pay"},{"de":"bar","en":"cash"},{"de":"die Einkaufstasche, -n","en":"shopping bag"},{"de":"die Kleidung","en":"clothes"}]'::jsonb,
  questions = '[{"question_de":"Wann ist der Supermarkt nicht offen?","question_en":"When is the supermarket not open?","answer_de":"Der Supermarkt ist am Sonntag nicht offen.","answer_en":"The supermarket is not open on Sunday."},{"question_de":"Wo kauft die Person Obst und Gemüse?","question_en":"Where does the person buy fruit and vegetables?","answer_de":"Sie kauft Obst und Gemüse von den Bauern.","answer_en":"She buys fruit and vegetables from the farmers."},{"question_de":"Wo kauft die Person Kleidung?","question_en":"Where does the person buy clothes?","answer_de":"Sie kauft Kleidung in der Stadt.","answer_en":"She buys clothes in the city."},{"question_de":"Wie bezahlt die Person lieber?","question_en":"How does the person prefer to pay?","answer_de":"Sie bezahlt lieber mit der EC-Karte.","answer_en":"She prefers to pay with her debit card."},{"question_de":"Was bringt die Person immer mit?","question_en":"What does the person always bring?","answer_de":"Sie bringt immer ihre Einkaufstasche mit.","answer_en":"She always brings her shopping bag."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Die Person kauft nur einmal pro Monat ein.","statement_en":"The person only shops once a month.","answer":"falsch","explanation_de":"Die Person kauft einmal pro Woche ein, nicht einmal pro Monat."},{"type":"rf","statement_de":"Die Person kauft Kleidung in der Stadt.","statement_en":"The person buys clothes in the city.","answer":"richtig","explanation_de":"Der Text sagt: Kleidung kaufe ich in der Stadt."},{"type":"rf","statement_de":"Die Person kauft am Samstag Obst und Gemüse.","statement_en":"On Saturday the person buys fruit and vegetables.","answer":"richtig","explanation_de":"Der Text sagt: Am Samstag gehe ich oft zum Wochenmarkt. Dort kaufe ich Obst und Gemüse."},{"type":"rf","statement_de":"Die Person bezahlt lieber bar.","statement_en":"The person prefers to pay in cash.","answer":"falsch","explanation_de":"Die Person bezahlt lieber mit der EC-Karte, nicht bar."},{"type":"rf","statement_de":"Die Person bringt immer ihre Einkaufstasche mit.","statement_en":"The person always brings her shopping bag.","answer":"richtig","explanation_de":"Der Text sagt: Ich bringe immer meine Einkaufstasche mit."},{"type":"choice","statement_de":"Wann kann man dort nicht einkaufen?","statement_en":"When can you not shop there?","options":["am Sonntag","am Samstag"],"answer":"am Sonntag","explanation_de":"Der Text sagt: Am Sonntag ist er nicht offen."}]'::jsonb,
  word_count = 118,
  estimated_reading_time = 2
