UPDATE public.reading_lessons SET
  title_de = 'Meine Wohnung',
  title_en = 'My Apartment',
  content_de = 'Ich habe eine Wohnung in Berlin. Ich wohne hier seit zwei Jahren. Die Wohnung ist klein, aber sie ist gemütlich.

Die Wohnung hat drei Zimmer, eine Küche und ein Badezimmer. Die Miete kostet 800 Euro pro Monat.

Das Wohnzimmer ist mein Lieblingsraum. Es ist groß und hell. Ich habe ein Sofa und einen Fernseher.

Das Schlafzimmer ist ruhig. Ich habe ein Bett und einen Kleiderschrank.

Die Küche ist klein, aber praktisch. Am Wochenende koche ich oft für meine Freunde.

Ich arbeite oft zu Hause. Ich habe ein Arbeitszimmer mit einem Schreibtisch und einem Bücherregal.

Der Balkon ist klein, aber schön. Im Sommer trinke ich dort gern Kaffee. Ich kann einen Park sehen!',
  content_en = 'I have an apartment in Berlin. I have been living here for two years. The apartment is small, but it is cozy.

The apartment has three rooms, a kitchen and a bathroom. The rent costs 800 euros per month.

The living room is my favorite room. It is big and bright. I have a sofa and a TV.

The bedroom is quiet. I have a bed and a wardrobe.

The kitchen is small but practical. On the weekend I often cook for my friends.

I often work at home. I have a study with a desk and a bookshelf.

The balcony is small but nice. In summer I like drinking coffee there. I can see a park!',
  key_vocabulary = '[{"de":"die Wohnung, -en","en":"apartment"},{"de":"das Zimmer, -","en":"room"},{"de":"das Wohnzimmer","en":"living room"},{"de":"das Schlafzimmer","en":"bedroom"},{"de":"die Küche, -n","en":"kitchen"},{"de":"der Balkon, -e","en":"balcony"},{"de":"die Miete, -n","en":"rent"},{"de":"der Schreibtisch, -e","en":"desk"},{"de":"das Bücherregal, -e","en":"bookshelf"},{"de":"praktisch","en":"practical"}]'::jsonb,
  questions = '[{"question_de":"Wie viele Zimmer hat die Wohnung?","question_en":"How many rooms does the apartment have?","answer_de":"Die Wohnung hat drei Zimmer, eine Küche und ein Badezimmer.","answer_en":"The apartment has three rooms, a kitchen and a bathroom."},{"question_de":"Was kostet die Miete?","question_en":"How much is the rent?","answer_de":"Die Miete kostet 800 Euro pro Monat.","answer_en":"The rent costs 800 euros per month."},{"question_de":"Was ist der Lieblingsraum der Person?","question_en":"What is the person''s favorite room?","answer_de":"Der Lieblingsraum ist das Wohnzimmer.","answer_en":"The favorite room is the living room."},{"question_de":"Was hat das Arbeitszimmer?","question_en":"What does the study have?","answer_de":"Es hat einen Schreibtisch und ein Bücherregal.","answer_en":"It has a desk and a bookshelf."},{"question_de":"Was kann die Person vom Balkon sehen?","question_en":"What can the person see from the balcony?","answer_de":"Sie kann einen Park sehen.","answer_en":"She can see a park."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Die Miete kostet 500 Euro pro Monat.","statement_en":"The rent costs 500 euros per month.","answer":"falsch","explanation_de":"Die Miete kostet 800 Euro, nicht 500."},{"type":"rf","statement_de":"Die Wohnung hat drei Zimmer.","statement_en":"The apartment has three rooms.","answer":"richtig","explanation_de":"Der Text sagt: Die Wohnung hat drei Zimmer."},{"type":"rf","statement_de":"Das Wohnzimmer ist der Lieblingsraum.","statement_en":"The living room is the favorite room.","answer":"richtig","explanation_de":"Der Text sagt: Das Wohnzimmer ist mein Lieblingsraum."},{"type":"rf","statement_de":"Vom Balkon kann man einen Park sehen.","statement_en":"From the balcony you can see a park.","answer":"richtig","explanation_de":"Der Text sagt: Ich kann einen Park sehen."},{"type":"rf","statement_de":"Das Schlafzimmer hat einen Schreibtisch.","statement_en":"The bedroom has a desk.","answer":"falsch","explanation_de":"Das Arbeitszimmer hat den Schreibtisch, nicht das Schlafzimmer."},{"type":"choice","statement_de":"Wie lange wohnt die Person schon hier?","statement_en":"How long has the person been living here?","options":["seit drei Jahren","seit zwei Jahren"],"answer":"seit zwei Jahren","explanation_de":"Der Text sagt: Ich wohne hier seit zwei Jahren."}]'::jsonb,
