UPDATE public.reading_lessons SET
  title_de = 'Eine E-Mail an eine Freundin',
  title_en = 'An Email to a Friend',
  content_de = 'Liebe Julia,

wie geht es dir? Mir geht es sehr gut, denn ich habe eine Wohnung in Köln! Sie ist klein, aber schön und hell. Das Viertel heißt Südstadt. Es gibt hier viele Cafés und einen Park.

Köln ist groß, und ich kenne noch niemanden. Ich mache einen Tanzkurs. Dort kann ich Leute treffen. Ich habe auch schon einen Job! Ich arbeite bei Buchhandlung Lang. Die Arbeit ist interessant, aber die Tage sind lang. Die Kollegen sind sehr nett.

Und jetzt meine Frage: Möchtest du mich besuchen? Du kannst am Wochenende kommen. Wir können zusammen die Stadt und den Dom sehen. Wann hast du Zeit? Schreib bald!

Viele Grüße
deine Emma',
  content_en = 'Dear Julia,

How are you? I am doing very well, because I have an apartment in Cologne! It is small, but nice and bright. The neighborhood is called Südstadt. There are lots of cafés here and a park.

Cologne is big, and I don''t know anyone yet. I am taking a dance class. There I can meet people. I also already have a job! I work at Buchhandlung Lang. The work is interesting, but the days are long. My colleagues are very nice.

And now my question: Would you like to visit me? You can come on the weekend. We can see the city and the cathedral together. When do you have time? Write soon!

Best wishes
your Emma',
  key_vocabulary = '[{"de":"die Wohnung, -en","en":"apartment"},{"de":"hell","en":"bright"},{"de":"das Viertel, -","en":"neighborhood"},{"de":"der Tanzkurs, -e","en":"dance class"},{"de":"treffen","en":"to meet"},{"de":"der Job, -s","en":"job"},{"de":"die Buchhandlung, -en","en":"bookshop"},{"de":"besuchen","en":"to visit"},{"de":"der Dom, -e","en":"cathedral"},{"de":"schreiben","en":"to write"}]'::jsonb,
  questions = '[{"question_de":"Warum geht es Emma sehr gut?","question_en":"Why is Emma doing very well?","answer_de":"Sie hat jetzt eine Wohnung in Köln.","answer_en":"She now has an apartment in Cologne."},{"question_de":"Wie ist Emmas Wohnung?","question_en":"What is Emma''s apartment like?","answer_de":"Die Wohnung ist klein, aber schön und hell.","answer_en":"The apartment is small, but nice and bright."},{"question_de":"Was macht Emma in Köln?","question_en":"What is Emma doing in Cologne?","answer_de":"Sie macht einen Tanzkurs.","answer_en":"She is taking a dance class."},{"question_de":"Wo arbeitet Emma?","question_en":"Where does Emma work?","answer_de":"Emma arbeitet bei Buchhandlung Lang.","answer_en":"Emma works at Buchhandlung Lang."},{"question_de":"Was können Emma und Julia am Wochenende machen?","question_en":"What can Emma and Julia do on the weekend?","answer_de":"Sie können die Stadt und den Dom sehen.","answer_en":"They can see the city and the cathedral."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Emma hat jetzt eine Wohnung in Köln.","statement_en":"Emma now has an apartment in Cologne.","answer":"richtig","explanation_de":"Der Text sagt: Ich habe eine Wohnung in Köln."},{"type":"rf","statement_de":"Emma arbeitet bei Buchhandlung Lang.","statement_en":"Emma works at Buchhandlung Lang.","answer":"richtig","explanation_de":"Der Text sagt: Ich arbeite bei Buchhandlung Lang."},{"type":"rf","statement_de":"Emmas Viertel heißt Nordstadt.","statement_en":"Emma''s neighborhood is called Nordstadt.","answer":"falsch","explanation_de":"Das Viertel heißt Südstadt, nicht Nordstadt."},{"type":"rf","statement_de":"Julia kann am Wochenende kommen.","statement_en":"Julia can come on the weekend.","answer":"richtig","explanation_de":"Der Text sagt: Du kannst am Wochenende kommen."},{"type":"rf","statement_de":"Emma kennt schon viele Leute in Köln.","statement_en":"Emma already knows many people in Cologne.","answer":"falsch","explanation_de":"Emma kennt noch niemanden in Köln."},{"type":"choice","statement_de":"Was möchte Emma mit Julia machen?","statement_en":"What does Emma want to do with Julia?","options":["die Stadt und den Dom sehen","am Wochenende arbeiten"],"answer":"die Stadt und den Dom sehen","explanation_de":"Der Text sagt: Wir können zusammen die Stadt und den Dom sehen."}]'::jsonb,
