UPDATE public.reading_lessons SET
  title_de = 'Am Wochenende',
  title_en = 'On the Weekend',
  content_de = 'Endlich Freitag! Max und Sara planen das Wochenende. Am Samstagmorgen möchte Max lange schlafen. Aber Sara sagt: „Wir müssen früh aufstehen.“ Der Wochenmarkt beginnt um acht Uhr. Sie möchten Gemüse, Obst und Blumen kaufen.

Am Nachmittag möchte Max Fußball spielen. Sara möchte lieber schwimmen. Am Abend möchten beide einen Film sehen. Max möchte einen Actionfilm, aber Sara möchte eine Komödie. Vielleicht sehen sie beide Filme!

Am Sonntag müssen Max und Sara zu Hause viel machen. Max muss die Wohnung putzen, und Sara muss Wäsche waschen. Danach machen sie vielleicht eine Radtour. Um sechs Uhr kommen Freunde zum Abendessen. Sara möchte Lasagne kochen. Das Wochenende ist kurz, aber sie können viel machen!',
  content_en = 'Finally Friday! Max and Sara are planning the weekend. On Saturday morning Max would like to sleep in. But Sara says: "We have to get up early." The weekly market starts at eight o''clock. They want to buy vegetables, fruit and flowers.

In the afternoon Max wants to play football. Sara would rather swim. In the evening they both want to watch a film. Max wants an action film, but Sara wants a comedy. Maybe they will watch both films!

On Sunday Max and Sara have a lot to do at home. Max has to clean the apartment, and Sara has to do the laundry. Afterwards they will maybe go on a bike tour. At six o''clock friends are coming for dinner. Sara wants to cook lasagna. The weekend is short, but they can do a lot!',
  key_vocabulary = '[{"de":"planen","en":"to plan"},{"de":"aufstehen","en":"to get up"},{"de":"früh","en":"early"},{"de":"der Film, -e","en":"film"},{"de":"die Komödie, -n","en":"comedy"},{"de":"putzen","en":"to clean"},{"de":"die Wäsche","en":"laundry"},{"de":"waschen","en":"to wash"},{"de":"die Radtour, -en","en":"bike tour"},{"de":"kochen","en":"to cook"}]'::jsonb,
  questions = '[{"question_de":"Wann beginnt der Wochenmarkt am Samstag?","question_en":"When does the weekly market start on Saturday?","answer_de":"Der Wochenmarkt beginnt um acht Uhr.","answer_en":"The weekly market starts at eight o''clock."},{"question_de":"Was möchte Max am Nachmittag machen?","question_en":"What does Max want to do in the afternoon?","answer_de":"Er möchte Fußball spielen.","answer_en":"He wants to play football."},{"question_de":"Welchen Film möchte Sara sehen?","question_en":"Which film does Sara want to see?","answer_de":"Sie möchte eine Komödie sehen.","answer_en":"She wants to see a comedy."},{"question_de":"Was muss Max am Sonntag machen?","question_en":"What does Max have to do on Sunday?","answer_de":"Er muss die Wohnung putzen.","answer_en":"He has to clean the apartment."},{"question_de":"Wer kommt am Sonntag um sechs Uhr?","question_en":"Who is coming on Sunday at six o''clock?","answer_de":"Um sechs Uhr kommen Freunde zum Abendessen.","answer_en":"At six o''clock friends are coming for dinner."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Der Wochenmarkt beginnt um acht Uhr.","statement_en":"The weekly market starts at eight o''clock.","answer":"richtig","explanation_de":"Der Text sagt: Der Wochenmarkt beginnt um acht Uhr."},{"type":"rf","statement_de":"Max möchte am Nachmittag schwimmen.","statement_en":"Max wants to swim in the afternoon.","answer":"falsch","explanation_de":"Max möchte Fußball spielen; Sara möchte schwimmen."},{"type":"rf","statement_de":"Max muss am Sonntag die Wohnung putzen.","statement_en":"Max has to clean the apartment on Sunday.","answer":"richtig","explanation_de":"Der Text sagt: Max muss die Wohnung putzen."},{"type":"rf","statement_de":"Am Sonntagabend kommen Freunde zu Besuch.","statement_en":"On Sunday evening friends are coming to visit.","answer":"richtig","explanation_de":"Der Text sagt: Um sechs Uhr kommen Freunde zum Abendessen."},{"type":"rf","statement_de":"Sara möchte einen Actionfilm sehen.","statement_en":"Sara wants to see an action film.","answer":"falsch","explanation_de":"Sara möchte eine Komödie sehen; Max möchte den Actionfilm."},{"type":"choice","statement_de":"Was möchte Sara zum Abendessen kochen?","statement_en":"What does Sara want to cook for dinner?","options":["Schnitzel","Lasagne"],"answer":"Lasagne","explanation_de":"Der Text sagt: Sara möchte Lasagne kochen."}]'::jsonb,
