UPDATE public.reading_lessons SET
  title_de = 'Mit dem Zug durch Deutschland',
  title_en = 'Through Germany by Train',
  content_de = 'Tom möchte seine Schwester in München besuchen. Er wohnt in Hamburg. Die Reise ist lang: fast 800 Kilometer. Aber Tom fliegt nicht gern. Er fährt lieber mit dem Zug. Er kann dann lesen und arbeiten.

Tom kauft eine Fahrkarte. Die Fahrt mit dem ICE kostet 89 Euro. Das ist teuer! Aber Tom hat eine BahnCard. Mit der BahnCard bekommt er 25 Prozent Rabatt.

Tom sucht seinen Zug: ICE 787 nach München. Abfahrt ist um 10:40 Uhr, Gleis 14. Dann kommt eine Durchsage: „Der ICE 787 hat 20 Minuten Verspätung.“

Die Fahrt dauert sechs Stunden. Tom sieht Städte, Felder und Berge. Um 17 Uhr ist er in München. Seine Schwester wartet dort. „Willkommen in München!“, sagt sie.',
  content_en = 'Tom wants to visit his sister in Munich. He lives in Hamburg. The journey is long: almost 800 kilometers. But Tom does not like flying. He prefers going by train. He can then read and work.

Tom buys a ticket. The trip on the ICE costs 89 euros. That is expensive! But Tom has a BahnCard. With the BahnCard he gets a 25 percent discount.

Tom looks for his train: ICE 787 to Munich. Departure is at 10:40, platform 14. Then an announcement comes: "The ICE 787 is delayed by 20 minutes."

The journey takes six hours. Tom sees cities, fields and mountains. At 5 p.m. he is in Munich. His sister is waiting there. "Welcome to Munich!", she says.',
  key_vocabulary = '[{"de":"die Reise, -n","en":"trip"},{"de":"die Fahrkarte, -n","en":"ticket"},{"de":"teuer","en":"expensive"},{"de":"der Rabatt, -e","en":"discount"},{"de":"die Abfahrt, -en","en":"departure"},{"de":"das Gleis, -e","en":"platform"},{"de":"die Durchsage, -n","en":"announcement"},{"de":"die Verspätung, -en","en":"delay"},{"de":"die Fahrt, -en","en":"journey"},{"de":"besuchen","en":"to visit"}]'::jsonb,
  questions = '[{"question_de":"Warum fährt Tom lieber mit dem Zug?","question_en":"Why does Tom prefer to go by train?","answer_de":"Er kann dann lesen und arbeiten.","answer_en":"He can then read and work."},{"question_de":"Was kostet die Fahrt mit dem ICE?","question_en":"How much does the trip on the ICE cost?","answer_de":"Die Fahrt kostet 89 Euro.","answer_en":"The trip costs 89 euros."},{"question_de":"Wie viel Rabatt bekommt Tom mit der BahnCard?","question_en":"How much discount does Tom get with the BahnCard?","answer_de":"Er bekommt 25 Prozent Rabatt.","answer_en":"He gets a 25 percent discount."},{"question_de":"Wie viel Verspätung hat der ICE 787?","question_en":"How delayed is the ICE 787?","answer_de":"Der Zug hat 20 Minuten Verspätung.","answer_en":"The train is delayed by 20 minutes."},{"question_de":"Wie lange dauert die Fahrt nach München?","question_en":"How long does the journey to Munich take?","answer_de":"Die Fahrt dauert sechs Stunden.","answer_en":"The journey takes six hours."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Die Fahrt mit dem ICE kostet 89 Euro.","statement_en":"The trip on the ICE costs 89 euros.","answer":"richtig","explanation_de":"Der Text sagt: Die Fahrt mit dem ICE kostet 89 Euro."},{"type":"rf","statement_de":"Der Zug fährt von Gleis 14.","statement_en":"The train leaves from platform 14.","answer":"richtig","explanation_de":"Der Text sagt: Gleis 14."},{"type":"rf","statement_de":"Tom fährt mit dem Bus nach München.","statement_en":"Tom travels to Munich by bus.","answer":"falsch","explanation_de":"Tom fährt mit dem Zug, nicht mit dem Bus."},{"type":"rf","statement_de":"Mit der BahnCard bekommt Tom 50 Prozent Rabatt.","statement_en":"With the BahnCard Tom gets a 50 percent discount.","answer":"falsch","explanation_de":"Tom bekommt 25 Prozent Rabatt, nicht 50."},{"type":"rf","statement_de":"Tom ist am Nachmittag in München.","statement_en":"Tom is in Munich in the afternoon.","answer":"richtig","explanation_de":"Der Text sagt: Um 17 Uhr ist er in München."},{"type":"choice","statement_de":"Was braucht Tom für den Rabatt?","statement_en":"What does Tom need for the discount?","options":["eine BahnCard","eine Fahrkarte"],"answer":"eine BahnCard","explanation_de":"Der Text sagt: Tom hat eine BahnCard. Mit der BahnCard bekommt er Rabatt."}]'::jsonb,
  word_count = 116,
  estimated_reading_time = 2
WHERE id = 'f26af6bf-6a1e-40c6-808e-b4b75b61d6d8'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

UPDATE public.reading_lessons SET
  title_de = 'Beim Bäcker',
  title_en = 'At the Bakery',
  content_de = 'Es ist Samstagmorgen, halb neun. Frau Schmidt geht zum Bäcker. Beim Bäcker Lang ist immer viel los. Sie wartet kurz.

Die Verkäuferin lächelt: „Guten Morgen! Was darf es sein?“ „Ich möchte sechs Brötchen, bitte“, sagt Frau Schmidt. „Mit Körnern oder ohne?“ „Vier ohne Körner und zwei mit Körnern, bitte.“

Der Apfelkuchen ist lecker. „Was kostet ein Stück Apfelkuchen?“ „Ein Stück kostet 3,20 Euro.“ „Gut, dann zwei Stück, bitte.“

Die Verkäuferin rechnet: „Sechs Brötchen kosten 3,60 Euro. Das macht zusammen 10,00 Euro.“ Frau Schmidt bezahlt bar. Sie gibt 15 Euro und bekommt 5,00 Euro Wechselgeld. „Schönes Wochenende!“, sagt die Verkäuferin. „Danke, gleichfalls!“

Zu Hause wartet schon die Familie. Brötchen am Samstag, das ist in Deutschland Tradition.',
  content_en = 'It is Saturday morning, half past eight. Mrs. Schmidt goes to the bakery. At Lang''s bakery there is always a lot going on. She waits briefly.

The saleswoman smiles: "Good morning! What can I get you?" "I would like six rolls, please," says Mrs. Schmidt. "With grains or without?" "Four without grains and two with grains, please."

The apple cake is delicious. "How much is one slice of apple cake?" "One slice costs 3.20 euros." "Good, then two slices, please."

The saleswoman adds it up: "Six rolls cost 3.60 euros. That comes to 10.00 euros altogether." Mrs. Schmidt pays in cash. She gives 15 euros and gets 5.00 euros change. "Have a nice weekend!" says the saleswoman. "Thanks, you too!"

At home the family is already waiting. Rolls on Saturday, that is a tradition in Germany.',
  key_vocabulary = '[{"de":"der Bäcker, -","en":"baker, bakery"},{"de":"die Verkäuferin, -nen","en":"saleswoman"},{"de":"lächeln","en":"to smile"},{"de":"der Apfelkuchen, -","en":"apple cake"},{"de":"das Stück, -e","en":"piece, slice"},{"de":"bar","en":"cash"},{"de":"das Wechselgeld","en":"change (money)"},{"de":"die Tradition, -en","en":"tradition"},{"de":"das Brötchen, -","en":"bread roll"}]'::jsonb,
  questions = '[{"question_de":"Wann geht Frau Schmidt zum Bäcker?","question_en":"When does Mrs. Schmidt go to the bakery?","answer_de":"Sie geht am Samstagmorgen um halb neun.","answer_en":"She goes on Saturday morning at half past eight."},{"question_de":"Wie viele Brötchen möchte Frau Schmidt?","question_en":"How many rolls does Mrs. Schmidt want?","answer_de":"Sie möchte sechs Brötchen.","answer_en":"She wants six rolls."},{"question_de":"Was kostet ein Stück Apfelkuchen?","question_en":"How much does a slice of apple cake cost?","answer_de":"Ein Stück kostet 3,20 Euro.","answer_en":"A slice costs 3.20 euros."},{"question_de":"Wie bezahlt Frau Schmidt?","question_en":"How does Mrs. Schmidt pay?","answer_de":"Sie bezahlt bar.","answer_en":"She pays in cash."},{"question_de":"Wie viel Wechselgeld bekommt Frau Schmidt?","question_en":"How much change does Mrs. Schmidt get?","answer_de":"Sie bekommt 5,00 Euro Wechselgeld.","answer_en":"She gets 5.00 euros change."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Frau Schmidt geht am Samstagmorgen zum Bäcker.","statement_en":"Mrs. Schmidt goes to the bakery on Saturday morning.","answer":"richtig","explanation_de":"Der Text sagt: Es ist Samstagmorgen. Frau Schmidt geht zum Bäcker."},{"type":"rf","statement_de":"Frau Schmidt möchte acht Brötchen.","statement_en":"Mrs. Schmidt wants eight rolls.","answer":"falsch","explanation_de":"Frau Schmidt möchte sechs Brötchen, nicht acht."},{"type":"rf","statement_de":"Frau Schmidt bezahlt mit Karte.","statement_en":"Mrs. Schmidt pays by card.","answer":"falsch","explanation_de":"Frau Schmidt bezahlt bar, nicht mit Karte."},{"type":"rf","statement_de":"Ein Stück Apfelkuchen kostet 3,20 Euro.","statement_en":"A slice of apple cake costs 3.20 euros.","answer":"richtig","explanation_de":"Der Text sagt: Ein Stück kostet 3,20 Euro."},{"type":"rf","statement_de":"Frau Schmidt bezahlt zusammen 10,00 Euro.","statement_en":"Mrs. Schmidt pays 10.00 euros altogether.","answer":"richtig","explanation_de":"Der Text sagt: Das macht zusammen 10,00 Euro."},{"type":"choice","statement_de":"Wie viele Brötchen ohne Körner kauft Frau Schmidt?","statement_en":"How many rolls without grains does Mrs. Schmidt buy?","options":["zwei","vier"],"answer":"vier","explanation_de":"Der Text sagt: Vier ohne Körner und zwei mit Körnern, bitte."}]'::jsonb,
  word_count = 115,
  estimated_reading_time = 2
WHERE id = 'da67d132-0f15-4ef9-b6e8-5323ad741a37'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

