INSERT INTO public.reading_lessons
  (level, title_de, title_en, topic, content_de, content_en, key_vocabulary, questions, checks, word_count, difficulty, estimated_reading_time, order_index)
SELECT
  'a1.2', 'Zwei kurze E-Mails (wie in der Prüfung, Teil 1)', 'Two short emails (exam-style, part 1)', 'Prüfungsformat',
  'Lies die zwei E-Mails. Sind die Sätze richtig oder falsch?

E-Mail 1

Hallo Lisa,

wie geht''s? Am Samstag mache ich eine Grillparty. Kommst du mit? Die Party beginnt um 16 Uhr. Meine Adresse ist Gartenstraße 5. Bring bitte einen Salat mit! Meine Schwester kommt auch. Wir spielen vielleicht Fußball. Das ist bestimmt lustig!

Schreib bald!

Liebe Grüße
Anna

E-Mail 2

Sehr geehrter Herr Bauer,

meine Heizung funktioniert nicht. Es ist sehr kalt. Können Sie das bitte reparieren? Ich bin diese Woche jeden Tag zu Hause. Sie können auch am Wochenende kommen. Meine Wohnung hat die Nummer 12. Bitte rufen Sie mich an. Meine Telefonnummer ist 030 5566778. Vielen Dank für Ihre Hilfe.

Mit freundlichen Grüßen
Sabine Kern', 'Read the two emails. Are the sentences true or false?

Email 1

Hi Lisa,

how are you? On Saturday I''m having a barbecue party. Are you coming? The party starts at 4 p.m. My address is Gartenstraße 5. Please bring a salad! My sister is coming too. We might play football. That is bound to be fun!

Write soon!

Best wishes
Anna

Email 2

Dear Mr. Bauer,

my heating is not working. It is very cold. Could you please repair it? I am at home every day this week. You can also come on the weekend. My apartment is number 12. Please call me. My phone number is 030 5566778. Thank you very much for your help.

Kind regards
Sabine Kern',
  '[{"de":"die Grillparty, -s","en":"barbecue party"},{"de":"mitbringen","en":"to bring along"},{"de":"die Adresse, -n","en":"address"},{"de":"der Salat, -e","en":"salad"},{"de":"die Heizung, -en","en":"heating"},{"de":"kalt","en":"cold"},{"de":"funktionieren","en":"to function, work"},{"de":"reparieren","en":"to repair"},{"de":"die Telefonnummer, -n","en":"phone number"},{"de":"sehr geehrter / sehr geehrte","en":"dear (formal salutation)"},{"de":"mit freundlichen Grüßen","en":"kind regards (formal closing)"}]'::jsonb, '[]'::jsonb, '[{"type":"rf","statement_de":"Anna feiert am Samstag.","statement_en":"Anna is celebrating on Saturday.","answer":"richtig","explanation_de":"Anna schreibt: Am Samstag mache ich eine Grillparty."},{"type":"rf","statement_de":"Die Party beginnt um 18 Uhr.","statement_en":"The party starts at 6 p.m.","answer":"falsch","explanation_de":"Die Party beginnt um 16 Uhr, nicht um 18 Uhr."},{"type":"rf","statement_de":"Lisa soll einen Kuchen mitbringen.","statement_en":"Lisa should bring a cake.","answer":"falsch","explanation_de":"Anna bittet um einen Salat, nicht um einen Kuchen."},{"type":"rf","statement_de":"Frau Kern hat diese Woche viel Zeit zu Hause.","statement_en":"Mrs. Kern has a lot of time at home this week.","answer":"richtig","explanation_de":"Frau Kern schreibt: Ich bin diese Woche jeden Tag zu Hause. Sie können auch am Wochenende kommen."},{"type":"rf","statement_de":"Frau Kerns Wohnung hat die Nummer 12.","statement_en":"Mrs. Kern''s apartment is number 12.","answer":"richtig","explanation_de":"Frau Kern schreibt: Meine Wohnung hat die Nummer 12."},{"type":"rf","statement_de":"Frau Kern hat es zu warm.","statement_en":"Mrs. Kern''s place is too warm.","answer":"falsch","explanation_de":"Frau Kern schreibt: Es ist sehr kalt, nicht zu warm."}]'::jsonb,
  117, 2, 3, 9
WHERE NOT EXISTS (
  SELECT 1 FROM public.reading_lessons WHERE level = 'a1.2' AND title_de = 'Zwei kurze E-Mails (wie in der Prüfung, Teil 1)'
);

INSERT INTO public.reading_lessons
  (level, title_de, title_en, topic, content_de, content_en, key_vocabulary, questions, checks, word_count, difficulty, estimated_reading_time, order_index)
SELECT
  'a1.2', 'Anzeigen zu Wohnen und Arbeit (wie in der Prüfung, Teil 2)', 'Ads about housing and work (exam-style, part 2)', 'Prüfungsformat',
  'Lies die Situation und die zwei Anzeigen. Welche Anzeige passt: a oder b?

Situation 1: Du suchst eine Wohnung in Rostock für unter 500 Euro.

(a) Wohnung in Rostock, 50 m², 620 Euro warm, frei ab 15. Januar. Telefon: 0381 774411.

(b) Wohnung in Rostock, 45 m², 480 Euro warm, frei ab 15. Januar. Telefon: 0381 774422.

Situation 2: Du suchst eine Stelle als Verkäufer/in. Du kannst nur vormittags arbeiten.

(a) Buchladen sucht Aushilfe: Montag bis Freitag, 8 bis 13 Uhr, 10 Euro pro Stunde. Telefon: 0521 663344.

(b) Buchladen sucht Aushilfe: Montag bis Freitag, 14 bis 19 Uhr, 10 Euro pro Stunde. Telefon: 0521 663345.

Situation 3: Du suchst Mathe-Nachhilfe für deine Tochter.

(a) Nachhilfe Mathematik: Frau Weber, Erfahrung mit Kindern, 15 Euro pro Stunde. Telefon: 0711 445566.

(b) Nachhilfe Englisch: Herr Fischer, Erfahrung mit Erwachsenen, 20 Euro pro Stunde. Telefon: 0711 778899.

Situation 4: Du arbeitest tagsüber. Du suchst einen Deutschkurs am Abend.

(a) Deutschkurs, Dienstag und Freitag, 8 bis 10 Uhr, Sprachschule Süd. Anmeldung: 089 221144.

(b) Deutschkurs, Dienstag und Freitag, 19 bis 21 Uhr, Sprachschule Süd. Anmeldung: 089 221144.

Situation 5: Du fährst jeden Tag von Bremen nach Hamburg zur Arbeit.

(a) Fahrgemeinschaft gesucht: Bremen–Hamburg, täglich, Abfahrt 7 Uhr. Kontakt: 0421 665511.

(b) Fahrgemeinschaft gesucht: Hannover–Hamburg, täglich, Abfahrt 7 Uhr. Kontakt: 0511 665511.', 'Read the situation and the two ads. Which ad fits: a or b?

Situation 1: You are looking for an apartment in Rostock for under 500 euros.

(a) Apartment in Rostock, 50 m², 620 euros warm rent, available from January 15th. Phone: 0381 774411.

(b) Apartment in Rostock, 45 m², 480 euros warm rent, available from January 15th. Phone: 0381 774422.

Situation 2: You are looking for a position as a sales assistant. You can only work mornings.

(a) Bookshop looking for help: Monday to Friday, 8 a.m. to 1 p.m., 10 euros per hour. Phone: 0521 663344.

(b) Bookshop looking for help: Monday to Friday, 2 p.m. to 7 p.m., 10 euros per hour. Phone: 0521 663345.

Situation 3: You are looking for math tutoring for your daughter.

(a) Math tutoring: Mrs. Weber, experience with children, 15 euros per hour. Phone: 0711 445566.

(b) English tutoring: Mr. Fischer, experience with adults, 20 euros per hour. Phone: 0711 778899.

Situation 4: You work during the day. You are looking for a German course in the evening.

(a) German course, Tuesday and Friday, 8 to 10 a.m., Sprachschule Süd. Registration: 089 221144.

(b) German course, Tuesday and Friday, 7 to 9 p.m., Sprachschule Süd. Registration: 089 221144.

Situation 5: You drive from Bremen to Hamburg for work every day.

(a) Carpool wanted: Bremen–Hamburg, daily, departure 7 a.m. Contact: 0421 665511.

(b) Carpool wanted: Hannover–Hamburg, daily, departure 7 a.m. Contact: 0511 665511.',
  '[{"de":"die Wohnung, -en","en":"apartment"},{"de":"die Aushilfe, -n","en":"part-time helper"},{"de":"die Stelle, -n","en":"position, job"},{"de":"vormittags","en":"in the mornings"},{"de":"die Nachhilfe","en":"tutoring"},{"de":"die Erfahrung, -en","en":"experience"},{"de":"die Sprachschule, -n","en":"language school"},{"de":"die Anmeldung, -en","en":"registration"},{"de":"die Fahrgemeinschaft, -en","en":"carpool"},{"de":"täglich","en":"daily"}]'::jsonb, '[]'::jsonb, '[{"type":"choice","statement_de":"Situation 1: Wohnung in Rostock — welche Anzeige passt?","statement_en":"Situation 1: Apartment in Rostock — which ad fits?","options":["a","b"],"answer":"b","explanation_de":"Anzeige b kostet 480 Euro, unter 500 Euro. Anzeige a kostet 620 Euro."},{"type":"choice","statement_de":"Situation 2: Stelle am Vormittag — welche Anzeige passt?","statement_en":"Situation 2: Position in the morning — which ad fits?","options":["a","b"],"answer":"a","explanation_de":"Anzeige a ist am Vormittag. Anzeige b ist am Nachmittag und Abend."},{"type":"choice","statement_de":"Situation 3: Mathe-Nachhilfe — welche Anzeige passt?","statement_en":"Situation 3: Math tutoring — which ad fits?","options":["a","b"],"answer":"a","explanation_de":"Anzeige a ist für Mathematik. Anzeige b ist für Englisch."},{"type":"choice","statement_de":"Situation 4: Deutschkurs am Abend — welche Anzeige passt?","statement_en":"Situation 4: German course in the evening — which ad fits?","options":["a","b"],"answer":"b","explanation_de":"Anzeige b ist von 19 bis 21 Uhr. Anzeige a ist von 8 bis 10 Uhr."},{"type":"choice","statement_de":"Situation 5: Fahrgemeinschaft von Bremen — welche Anzeige passt?","statement_en":"Situation 5: Carpool from Bremen — which ad fits?","options":["a","b"],"answer":"a","explanation_de":"Anzeige a fährt von Bremen nach Hamburg. Anzeige b fährt von Hannover nach Hamburg."}]'::jsonb,
  217, 2, 3, 10
WHERE NOT EXISTS (
  SELECT 1 FROM public.reading_lessons WHERE level = 'a1.2' AND title_de = 'Anzeigen zu Wohnen und Arbeit (wie in der Prüfung, Teil 2)'
);

COMMIT;
